def iou(shape, bbox_shape, bbox):
    # scale 'shape' to bbox (nearest-neighbor) and compare with bbox_shape
    h0=max(r for r,_ in shape)-min(r for r,_ in shape)+1
    w0=max(c for _,c in shape)-min(c for _,c in shape)+1
    rs=[r for r,_ in shape]; cs=[c for _,c in shape]; r0,c0=min(rs),min(cs)
    S={( (r-r0)*bbox[0]//h0, (c-c0)*bbox[1]//w0 ) for r,c in shape}
    A=bbox_shape; inter=len(S&A); uni=len(S|A)
    return inter/uni
