import copy
def transform(grid):
    g=[row[:] for row in grid]
    H=len(g); W=len(g[0])
    def cls(v):
        seen=set(); out=[]
        for i_ in range(H):
            for j_ in range(W):
                if g[i_][j_]==v and (i_,j_) not in seen:
                    st=[(i_,j_)]; comp=set()
                    while st:
                        a,b=st.pop()
                        if (a,b) in comp: continue
                        comp.add((a,b))
                        for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                            na,nb=a+da,b+db
                            if 0<=na<H and 0<=nb<W and g[na][nb]==v and (na,nb) not in comp: st.append((na,nb))
                    seen|=comp; out.append(comp)
        return out
    def rel(c_):
        r0=min(x for x,_ in c_); c0=min(y for _,y in c_)
        return frozenset((x-r0,y-c0) for x,y in c_)
    # paint = color with exactly one cluster shaped like an L (corner cell with 2 arms)
    paint=None
    for v_ in sorted({g[i_][j_] for i_ in range(H) for j_ in range(W)}):
        cs=cls(v_)
        if len(cs)!=1: continue
        c_=cs[0]
        deg={p:0 for p in c_}
        for (a,b) in c_:
            for da,db in ((1,0),(-1,0),(0,1),(0,-1)):
                if (a+da,b+db) in c_: deg[(a,b)]+=1
        if len(c_)>=4 and sum(1 for p in c_ if deg[p]==1)==2 and sum(1 for p in c_ if deg[p]==2)>=1:
            paint=v_; break
    if paint is None: return g
    # find identical cross-color twin pairs (same normalized shape, single copy each in two colors)
    shapes={}
    for v_ in sorted({g[i_][j_] for i_ in range(H) for j_ in range(W)}):
        if v_==paint: continue
        for c_ in cls(v_):
            shapes.setdefault(rel(c_),[]).append((v_,c_))
    best=None
    for s_,lst in shapes.items():
        colors={v_ for v_,_ in lst}
        if len(lst)==2 and len(colors)==2 and len(s_)>=3:
            best=lst  # unique 1+1 family (take the one with smallest shape if several)
    if best is None: return g
    (v1,c1),(v2,c2)=best
    def span(c_): return (min(x for x,_ in c_),max(x for x,_ in c_),min(y for _,y in c_),max(y for _,y in c_))
    pc=[c_ for c_ in cls(paint)][0]
    pr0,pr1,pc0,pc1=span(pc)
    def overlap(c_):
        r0,r1,c0,c1=span(c_)
        return (r0<=pr1 and r1>=pr0) + (c0<=pc1 and c1>=pc0)
    # recolor the copy with LESS overlap with the paint's span
    tgt = c2 if overlap(c2)<overlap(c1) else c1
    for (a,b) in tgt: g[a][b]=paint
    return g
